package com.fooddelivery.restaurant.service;import java.util.*;import org.springframework.stereotype.Service;import com.fooddelivery.restaurant.entity.Restaurant;import com.fooddelivery.restaurant.repository.RestaurantRepository;@Service public class RestaurantService{private final RestaurantRepository r;public RestaurantService(RestaurantRepository r){this.r=r;}public Restaurant save(Restaurant x){return r.save(x);}public List<Restaurant> all(){return r.findAll();}public Restaurant get(String id){return r.findById(id).orElseThrow(()->new NoSuchElementException("Restaurant not found"));}}
